import { cn } from "@/lib/utils";

const LOGO_SYMBOL_ID = "dea-logo";
const LOGO_VIEW_BOX = "0 0 992 1586";

/**
 * Logo oficial minimalista do grupo.
 *
 * O desenho é grande (~73 kB de path), então ele é definido uma única vez por
 * documento em <LogoDefs /> e referenciado aqui com <use>. Assim o HTML não
 * carrega duas cópias por causa do header e do rodapé.
 *
 * Decorativa: o nome do grupo aparece escrito ao lado.
 */
export function Logo({ className }: { className?: string }) {
  return (
    <svg
      viewBox={LOGO_VIEW_BOX}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      className={cn("h-9 w-auto shrink-0", className)}
    >
      <use href={`#${LOGO_SYMBOL_ID}`} />
    </svg>
  );
}

